def solve(x):
    def dfs(node, visited):
        visited.add(node)
        for neighbor in x["edges"]:
            if neighbor[0] == node and neighbor[1] not in visited:
                dfs(neighbor[1], visited)
        return visited

    visited = set()
    result = dfs(x["start"], visited)
    result.remove(x["start"])
    return sorted(result)
